import numpy as np
from scipy.optimize import minimize

def equations(p):
    x, y, z = p
    eq1 = x**2 + y**2 + z**2 - 3
    eq2 = x*y**3 + y*z**3 + z*x**3 - 3
    return eq1**2 + eq2**2

# Let's refine the search by trying a larger range of initial points
# and also testing the uniqueness of the solutions found.
starts = []
for x in np.linspace(-1.8, 1.8, 10):
    for y in np.linspace(-1.8, 1.8, 10):
        for z in np.linspace(-1.8, 1.8, 10):
            starts.append((x, y, z))

results = []
for start in starts:
    res = minimize(equations, start)
    if res.fun < 1e-6:
        results.append(res.x)

unique_results = []
for r in results:
    is_new = True
    for ur in unique_results:
        if np.allclose(r, ur, atol=1e-3):
            is_new = False
            break
    if is_new:
        unique_results.append(r)

print(f"Found {len(unique_results)} unique solutions:")
for i, r in enumerate(unique_results):
    print(f"{i+1}: {r}")

