import numpy as np
from scipy.optimize import fsolve

def equations(p):
    x, y, z, lam = p
    return [y**3 + 3*z*x**2 - 2*lam*x,
            3*x*y**2 + z**3 - 2*lam*y,
            3*y*z**2 + x**3 - 2*lam*z,
            x**2 + y**2 + z**2 - 3]

solutions = []
for lam_val in np.linspace(-5, 5, 20):
    for x_guess in np.linspace(-1.8, 1.8, 3):
        for y_guess in np.linspace(-1.8, 1.8, 3):
            for z_guess in np.linspace(-1.8, 1.8, 3):
                sol = fsolve(lambda p: equations([p[0], p[1], p[2], lam_val]), [x_guess, y_guess, z_guess])
                if np.allclose(equations([sol[0], sol[1], sol[2], lam_val]), [0,0,0,0], atol=1e-5):
                    solutions.append((sol[0], sol[1], sol[2], lam_val))

unique_solutions = []
for s in solutions:
    is_new = True
    for us in unique_solutions:
        if np.allclose(s, us, atol=1e-3):
            is_new = False
            break
    if is_new:
        unique_solutions.append(s)

print(f"Unique solutions (x, y, z, lam): {unique_solutions}")
